INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Es wurde kein Format veröffentlicht', NULL, NULL, 'Katars Allgemeine Steuerbehörde hat weder ein E-Invoicing-Schema noch einen XML/UBL-Standard noch eine technische Spezifikation jeglicher Art veröffentlicht. Das GTA-eigene Dhareeba-Portal wurde direkt geprüft und enthält keinerlei E-Invoicing-Inhalte. Einige Branchenkommentare spekulieren, Katar könnte angesichts des regionalen Präzedenzfalls letztlich ein Clearance-Modell nach ZATCA-Vorbild Saudi-Arabiens oder ein Peppol-Netzwerk nach Vorbild der VAE übernehmen -- doch dies ist Spekulation über eine noch nicht ausgearbeitete Regelung, keine bestätigte technische Entscheidung, und diese Seite behandelt es nicht als Tatsache.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was heute abgedeckt ist', '[["B2B", "Nicht festgelegt -- es besteht kein Mandat"], ["B2G", "Nicht festgelegt -- es besteht kein Mandat"], ["B2C", "Nicht festgelegt -- es besteht kein Mandat"], ["Mehrwertsteuersystem", "Noch nicht eingeführt, trotz einer im GCC-Mehrwertsteuer-Rahmenabkommen von 2016 eingegangenen Verpflichtung"]]', 'Jede Zeile dieser Tabelle sagt aus demselben Grund „nicht festgelegt" oder „noch nicht eingeführt": Katars E-Invoicing-Gesetz existiert nur als nicht erlassener Entwurf.', NULL FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was geschehen muss, bevor dies Realität wird', '[["Schritt 1 (erledigt)", "Der Ministerrat billigt den Gesetzentwurf und die Durchführungsverordnung -- 6. Mai 2026"], ["Schritt 2 (ausstehend)", "Prüfung durch den Schura-Rat -- kein Termin gemeldet"], ["Schritt 3 (ausstehend)", "Vorlage beim Emir zur Erlassung"], ["Schritt 4 (ausstehend)", "Veröffentlichung im Amtsblatt"]]', 'Dieser Tracker wird in dem Moment, in dem einer der ausstehenden Schritte unabhängig bestätigt wird, einen echten „im Tracker geführten" Meilenstein hinzufügen.', NULL FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Es gibt keinen Bußgeldkatalog — weil es kein Mandat gibt', NULL, NULL, 'Es gibt nichts zu sanktionieren: Katar hat keinerlei E-Invoicing-Anforderung erlassen, sodass kein Bußgeld- oder Sanktionskatalog daran anknüpft, wie (oder ob) Sie Rechnungen elektronisch ausstellen.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 Unbestätigte Branchen-Zeitpläne — hier bewusst nicht wiederholt', NULL, NULL, 'Einige Branchenberichte (z. B. Wafeq) nennen konkrete Termine wie „Meldungen ab Oktober 2026" oder „Durchsetzung ab Januar 2027", stellen dies aber ausdrücklich als Spekulation von Analysten dar, nicht als von der katarischen Regierung veröffentlichte Zahlen. Jede geprüfte, dem Offiziellen nahestehende Quelle (EY, KPMG, PwC, Thomson Reuters) erklärt klar, dass kein Umsetzungsfahrplan veröffentlicht wurde. Diese Seite wiederholt die spekulativen Termine nicht als Tatsache.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🌍 Einordnung: Der Rest des Golfs kommt schneller voran', NULL, NULL, 'Saudi-Arabiens Fatoora-System ist live und ausgereift; die VAE führen ab Juli 2026 schrittweise ein Peppol-basiertes B2B-Mandat ein; Oman hat ein laufendes Pilotprojekt. Katars am 6. Mai 2026 gebilligter Gesetzentwurf macht das Land zum dritten GCC-Staat mit einem konkreten gesetzgeberischen Schritt -- aber zum einzigen, das sich noch vollständig im Entwurfsstadium befindet, während Bahrain und Kuwait bislang überhaupt keinen formalen Schritt unternommen haben.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Heute gibt es nichts einzuhalten', 'In Katar ist derzeit kein E-Invoicing-Mandat in Kraft. Es ist weder eine Registrierung, eine Meldung noch eine Formatumstellung erforderlich oder überhaupt möglich.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Achten Sie auf die eigentlichen Signale der Erlassung', 'Der Gesetzentwurf wird an drei konkreten Punkten zur echten Nachricht: einer Abstimmung im Schura-Rat, einem Amiri-Dekret oder der Veröffentlichung im Amtsblatt. Bislang ist keiner dieser drei Schritte eingetreten.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Erwarten Sie im Falle einer Erlassung eine stufenweise Einführung nach Steuerpflichtigengröße', 'Jedes andere bisher aufgebaute GCC-E-Invoicing-Mandat (Saudi-Arabien, VAE, Oman) wurde in Wellen nach Steuerpflichtigengröße oder Umsatzstufe eingeführt statt auf einmal -- eine vernünftige Erwartung auch für Katar, wenngleich noch nicht bestätigt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Planen Sie nicht anhand inoffizieller Termine', 'Einige Branchenkommentare verbreiten konkrete 2026/2027-Termine für Katar. Keiner davon stützt sich auf ein katarisches Regierungsdokument -- behandeln Sie sie als Spekulation, nicht als Compliance-Frist, bis diese Seite etwas anderes angibt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Setzen Sie ein Lesezeichen für diese Seite', 'Dieser Tracker wird einen echten Meilenstein hinzufügen, die Statistiken aktualisieren und einen ordentlichen Compliance-Zeitplan veröffentlichen, sobald Katars Gesetzentwurf tatsächlich den Schura-Rat passiert oder erlassen wird.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'Allgemeine Steuerbehörde -- Dhareeba-Portal (allgemeine Steuerverwaltung; noch keine E-Invoicing-Inhalte)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'QA' AND p.url = 'https://dhareeba.gov.qa';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'EY-Steueralarm -- Zusammenfassung des Gesetzentwurfs (Branchenquelle, nicht von der Regierung veröffentlicht)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'QA' AND p.url = 'https://www.ey.com/en_gl/technical/tax-alerts/qatar-approves-draft-e-invoicing-law-and-implementing-regulations';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'qa-draft-law-2026', 'de',
  'Ministerrat billigt Entwurf eines E-Invoicing-Gesetzes -- noch nicht erlassen',
  'Am 6. Mai 2026 billigte der Ministerrat (das Kabinett) Katars den Entwurf eines E-Invoicing-Gesetzes samt Durchführungsverordnung -- direkt bestätigt durch EY, KPMG, PwC und Thomson Reuters/Pagero, die alle dieselbe einzelne Maßnahme beschreiben. Dies ist ein realer Schritt, aber kein Mandat: Der Entwurf muss noch die Prüfung durch den Schura-Rat durchlaufen und anschließend dem Emir zur Erlassung vorgelegt werden, und eine Veröffentlichung im Amtsblatt ist nicht erfolgt. Keine Quelle, weder offiziell noch aus der Branche, hat seit dem 6. Mai 2026 einen weiteren Schritt unabhängig bestätigt. Es wurde offiziell weder ein Umsetzungsdatum noch ein Steuerpflichtigen-Schwellenwert, ein Rechnungsmodell (Clearance oder Meldung) noch ein Bußgeldkatalog veröffentlicht -- einige Branchenkommentare spekulieren über einen Start 2027 oder ein Vorgehen nach saudischem/emiratischem Vorbild, doch nichts davon stützt sich auf ein katarisches Regierungsdokument, weshalb es auf dieser Seite nicht als Tatsache festgehalten wird. Katars Allgemeine Steuerbehörde verfügt noch über kein eigenes E-Invoicing-Portal, und Katar selbst hat die Mehrwertsteuer noch nicht eingeführt (weiterhin ausstehend unter dem GCC-Mehrwertsteuer-Rahmenabkommen von 2016) -- eine ungewöhnlich frühe Abfolge für ein E-Invoicing-Gesetz.',
  '["Derzeit ist keine Compliance-Maßnahme erforderlich oder überhaupt möglich -- es besteht kein Mandat, es gibt kein Portal, und es wurde kein Format veröffentlicht", "Planen Sie nicht anhand eines bestimmten, in Branchenkommentaren kursierenden Datums aus 2026/2027 -- keines davon stützt sich auf ein katarisches Regierungsdokument", "Achten Sie auf die Prüfung durch den Schura-Rat, ein Amiri-Dekret und die Veröffentlichung im Amtsblatt als die eigentlichen Signale dafür, dass dies vom Entwurf zum erlassenen Gesetz geworden ist"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-05-06-qatar-draft-elaw-approved', 'de',
  'Katar unternimmt seinen ersten gesetzgeberischen Schritt beim E-Invoicing -- bis zu einem Mandat ist es noch ein weiter Weg',
  'Katars Ministerrat billigte am 6. Mai 2026 den Entwurf eines E-Invoicing-Gesetzes samt Durchführungsverordnung -- ein realer erster Schritt, aber kein Mandat. Der Entwurf benötigt noch die Prüfung durch den Schura-Rat und die Zustimmung des Emir, es wurde weder ein Umsetzungsdatum noch ein Format veröffentlicht, und Katar hat noch nicht einmal die Mehrwertsteuer eingeführt.',
  '<h3>🇶🇦 Katar unternimmt seinen ersten gesetzgeberischen Schritt beim E-Invoicing -- bis zu einem Mandat ist es noch ein weiter Weg</h3>
<p>Am 6. Mai 2026 billigte Katars Ministerrat den Entwurf eines E-Invoicing-Gesetzes samt Durchführungsverordnung -- bestätigt durch EY, KPMG, PwC und Thomson Reuters/Pagero, die alle dieselbe einzelne Maßnahme beschreiben. Es ist die erste konkrete gesetzgeberische Bewegung, die dieser Tracker beim katarischen E-Invoicing gefunden hat, und stellt Katar neben Saudi-Arabien, die VAE und Oman als Golfstaat, der aktiv auf ein Mandat hinarbeitet.</p>
<p>Doch „Entwurf" bedeutet genau das: Das Gesetz muss noch die Prüfung durch den Schura-Rat durchlaufen, anschließend dem Emir zur Erlassung vorgelegt und schließlich im Amtsblatt veröffentlicht werden -- und mit Stand der Veröffentlichung dieser Nachricht wurde keiner dieser Schritte unabhängig bestätigt. Es wurde offiziell weder ein Umsetzungsdatum noch ein Steuerpflichtigen-Schwellenwert, ein technisches Format noch eine Bußgeldstruktur veröffentlicht. Einige Branchenkommentare spekulieren über einen Start 2027 oder ein Vorgehen nach saudischem/emiratischem Vorbild, doch nichts davon stützt sich auf ein katarisches Regierungsdokument. Wie früh sich das alles noch befindet, unterstreicht auch: Katar hat die Mehrwertsteuer trotz einer entsprechenden Verpflichtung im Rahmen des GCC-Mehrwertsteuer-Rahmenabkommens von 2016 bislang überhaupt noch nicht eingeführt -- eine ungewöhnliche Abfolge für ein Land, das nun ein E-Invoicing-Gesetz entwirft.</p>'
);


-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Pas encore de mandat — un projet de loi sur la facturation électronique a été approuvé par le Cabinet le 6 mai 2026, toujours en attente de l''examen du Conseil de la Choura et de l''assentiment de l''Émir',
  'Cette page d''analyse reflète le régime de facturation électronique du Qatar tel que confirmé par neuf sources vérifiées de manière indépendante (EY, KPMG, PwC, Thomson Reuters/Pagero, entre autres), ainsi que par une consultation directe du site de l''Autorité générale des impôts du Qatar, à la date du 10 août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le Qatar ne dispose actuellement d''aucune loi sur la facturation électronique promulguée, quelle qu''elle soit -- tout ce qui figure sur cette page décrit un projet en cours, pas une exigence en vigueur. Confirmez la situation actuelle directement auprès de l''Autorité générale des impôts du Qatar (gta.gov.qa) ou d''un conseiller fiscal qatari qualifié avant de vous fonder sur cette page pour vos décisions de planification.',
  'Le 6 mai 2026, le Conseil des ministres du Qatar a approuvé un projet de loi sur la facturation électronique et son règlement d''application -- la première véritable étape législative que ce suivi ait trouvée pour le Qatar. À la date de la dernière mise à jour de cette page, ce projet n''a pas progressé davantage : il nécessite encore l''examen du Conseil de la Choura et l''assentiment de l''Émir avant de devenir loi, et aucune source, officielle ou du secteur, n''a rapporté que l''une ou l''autre de ces étapes ait eu lieu. Cette chronologie ne comporte exactement qu''un seul événement daté, car exactement un seul événement s''est réellement produit.',
  'Aucun format, schéma ou norme technique de facturation électronique n''a été publié pour le Qatar. L''Autorité générale des impôts (GTA) du Qatar exploite le portail Dhareeba pour l''administration fiscale générale, mais celui-ci ne contient aucun contenu relatif à la facturation électronique à la date de la dernière mise à jour de cette page -- il n''existe aucun portail dédié à la facturation électronique vers lequel se tourner, contrairement au système Fatoora de l''Arabie saoudite ou au système fondé sur Peppol des Émirats arabes unis. Certains commentaires du secteur évoquent l''hypothèse que le Qatar pourrait suivre un modèle de type ZATCA saoudien ou de type Peppol émirati, mais il s''agit d''une spéculation portant sur une réglementation encore non rédigée, et non d''un choix technique confirmé ; cette page ne la présente pas comme un fait.',
  'Aucun champ d''application n''a été défini -- le projet de loi qatari ne précise pas encore si la facturation électronique s''appliquera au B2B, au B2G, au B2C ou à une combinaison de ceux-ci, quelles catégories d''assujettis ou quels seuils de transaction seraient couverts, ni si le modèle serait un système de clearance en temps réel (comme en Arabie saoudite) ou un système de simple déclaration. Tout ce qui touche au champ d''application reste ouvert tant que le règlement d''application n''est pas effectivement publié sous sa forme définitive et promulguée.',
  'Il n''y a rien à respecter aujourd''hui, car aucun mandat n''existe. Les étapes ci-dessous décrivent comment rester informé pendant que la loi qatarie suit son parcours législatif, et non comment se conformer à une exigence qui n''existe pas encore.',
  'Aucun barème de sanctions n''a été proposé ni publié en cas de non-conformité en matière de facturation électronique, pour la simple raison qu''aucune obligation de facturation électronique n''existe encore à laquelle rattacher une sanction. Les sanctions générales déjà existantes en matière d''administration fiscale au Qatar (sans lien spécifique avec la facturation électronique) continueraient vraisemblablement de s''appliquer à toute question fiscale sous-jacente, mais aucune structure d''amende propre à la facturation électronique ne figure dans aucune source consultée lors de cette recherche.',
  'Le Qatar n''a aucun mandat de facturation électronique, quel qu''il soit. Le 6 mai 2026, le Conseil des ministres a approuvé un projet de loi et son règlement d''application -- une première étape réelle, mais pas une promulgation. Le projet nécessite encore l''examen du Conseil de la Choura et l''assentiment de l''Émir, et la publication au Journal officiel n''a pas eu lieu. Aucune date de mise en œuvre, seuil d''assujettissement, format technique ni structure de sanctions n''a été officiellement publié, et le Qatar n''a même pas encore mis en œuvre la TVA, malgré un engagement du CCG datant de 2016 -- un enchaînement inhabituellement précoce pour une loi sur la facturation électronique. Ce suivi sera mis à jour immédiatement dès que le projet de loi sera réellement promulgué ou qu''un calendrier réel sera officiellement publié.',
  '📝'
FROM countries WHERE code = 'QA';

