INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Non promulguée', 'L''examen du Conseil de la Choura et l''assentiment amiri restent nécessaires' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'QA' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucune pour l''instant', 'Le Qatar n''a pas encore mis en œuvre la TVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'QA' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Rien de publié', 'Date de mise en œuvre, seuil et format technique' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'QA' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Aucun format n''a été publié', NULL, NULL, 'L''Autorité générale des impôts du Qatar n''a publié aucun schéma de facturation électronique, aucune norme XML/UBL ni aucune spécification technique d''aucune sorte. Le portail Dhareeba de la GTA lui-même a été consulté directement et ne contient aucun contenu relatif à la facturation électronique. Certains commentaires du secteur évoquent l''hypothèse que le Qatar pourrait éventuellement adopter un modèle de clearance de type ZATCA saoudien ou un réseau de type Peppol émirati, compte tenu du précédent régional -- mais il s''agit d''une spéculation portant sur une réglementation encore non rédigée, et non d''un choix technique confirmé, et cette page ne la présente pas comme un fait.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est couvert aujourd''hui', '[["B2B", "Non défini -- aucun mandat n''existe"], ["B2G", "Non défini -- aucun mandat n''existe"], ["B2C", "Non défini -- aucun mandat n''existe"], ["Régime de TVA", "Pas encore mis en œuvre, malgré un engagement pris au titre de l''accord unifié du CCG sur la TVA de 2016"]]', 'Chaque ligne de ce tableau indique « non défini » ou « pas encore mis en œuvre » pour la même raison : la loi qatarie sur la facturation électronique n''existe qu''à l''état de projet non promulgué.', NULL FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui doit se produire avant que cela devienne réalité', '[["Étape 1 (réalisée)", "Le Conseil des ministres approuve le projet de loi et le règlement d''application -- 6 mai 2026"], ["Étape 2 (en attente)", "Examen par le Conseil de la Choura -- aucune date communiquée"], ["Étape 3 (en attente)", "Soumission à l''Émir pour promulgation"], ["Étape 4 (en attente)", "Publication au Journal officiel"]]', 'Ce suivi ajoutera un véritable jalon « suivi » dès que l''une des étapes en attente sera confirmée de manière indépendante.', NULL FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Aucun barème de sanctions n''existe — car aucun mandat n''existe', NULL, NULL, 'Il n''y a rien à sanctionner : le Qatar n''a promulgué aucune obligation de facturation électronique d''aucune sorte, si bien qu''aucun barème d''amendes ou de sanctions n''est rattaché à la manière (ou à la question de savoir si) vous émettez vos factures par voie électronique.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Calendriers du secteur non confirmés — délibérément non repris ici', NULL, NULL, 'Certains articles du secteur (par exemple Wafeq) mentionnent des dates précises telles que « notifications en octobre 2026 » ou « entrée en vigueur en janvier 2027 », mais les présentent explicitement comme des spéculations d''analystes, et non comme des chiffres publiés par le gouvernement qatari. Chaque source proche de l''officiel consultée (EY, KPMG, PwC, Thomson Reuters) indique clairement qu''aucun calendrier de mise en œuvre n''a été publié. Cette page ne reprend pas ces dates spéculatives comme des faits.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🌍 Contexte : le reste du Golfe avance plus vite', NULL, NULL, 'Le système Fatoora de l''Arabie saoudite est opérationnel et mature ; les Émirats arabes unis déploient progressivement un mandat B2B fondé sur Peppol à partir de juillet 2026 ; Oman dispose d''un projet pilote actif. Le projet de loi qatari, approuvé le 6 mai 2026, fait du Qatar le troisième pays du CCG à franchir une étape législative concrète -- mais le seul encore entièrement au stade de projet, alors que Bahreïn et le Koweït n''ont pris aucune mesure formelle à ce jour.' FROM deep_dive_cards dc JOIN countries c ON dc.country_id = c.id WHERE c.code = 'QA' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Il n''y a rien à respecter aujourd''hui', 'Aucun mandat de facturation électronique n''est en vigueur au Qatar. Aucune inscription, déclaration ou modification de format n''est requise, ni même possible pour l''instant.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez les véritables signaux de promulgation', 'Le projet de loi deviendra une véritable actualité à trois moments précis : un vote du Conseil de la Choura, un décret amiri, ou une publication au Journal officiel. Aucun de ces trois événements ne s''est encore produit.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Attendez-vous à un déploiement progressif selon la taille des assujettis, en cas de promulgation', 'Chaque autre mandat de facturation électronique déjà mis en place dans le CCG (Arabie saoudite, Émirats arabes unis, Oman) a été déployé par vagues selon la taille des assujettis ou le niveau de chiffre d''affaires, plutôt que d''un seul coup -- une attente raisonnable pour le Qatar également, bien que non encore confirmée.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ne planifiez rien autour de dates non officielles', 'Certains commentaires du secteur font circuler des dates précises de 2026/2027 pour le Qatar. Aucune ne repose sur un document du gouvernement qatari -- considérez-les comme des spéculations, pas comme une échéance de conformité, tant que cette page n''indique pas le contraire.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ajoutez cette page à vos favoris', 'Ce suivi ajoutera un véritable jalon, mettra à jour les statistiques et publiera un calendrier de conformité approprié dès que le projet de loi qatari franchira réellement le Conseil de la Choura ou sera promulgué.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'QA' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'Autorité générale des impôts -- portail Dhareeba (administration fiscale générale ; aucun contenu de facturation électronique pour l''instant)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'QA' AND p.url = 'https://dhareeba.gov.qa';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'Alerte fiscale EY -- résumé du projet de loi (source du secteur, non publiée par le gouvernement)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'QA' AND p.url = 'https://www.ey.com/en_gl/technical/tax-alerts/qatar-approves-draft-e-invoicing-law-and-implementing-regulations';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'qa-draft-law-2026', 'fr',
  'Le Conseil des ministres approuve un projet de loi sur la facturation électronique -- pas encore promulgué',
  'Le 6 mai 2026, le Conseil des ministres (le Cabinet) du Qatar a approuvé un projet de loi sur la facturation électronique et son règlement d''application -- confirmé directement par EY, KPMG, PwC et Thomson Reuters/Pagero, qui décrivent tous la même action unique. Il s''agit d''une étape réelle, mais pas d''un mandat : le projet doit encore passer par l''examen du Conseil de la Choura, puis être soumis à l''Émir pour promulgation, et la publication au Journal officiel n''a pas eu lieu. Aucune source, officielle ou du secteur, n''a confirmé de manière indépendante une quelconque étape ultérieure depuis le 6 mai 2026. Aucune date de mise en œuvre, seuil d''assujettissement, modèle de facturation (clearance ou déclaration) ni barème de sanctions n''a été officiellement publié -- certains commentaires du secteur évoquent une entrée en vigueur en 2027 ou un déploiement à la saoudienne/émiratie, mais rien de tout cela ne repose sur un document du gouvernement qatari, et ce n''est donc pas présenté comme un fait sur cette page. L''Autorité générale des impôts du Qatar ne dispose pas encore d''un portail dédié à la facturation électronique, et le Qatar lui-même n''a pas encore mis en œuvre la TVA (toujours en attente au titre de l''accord unifié du CCG sur la TVA de 2016) -- un enchaînement inhabituellement précoce pour une loi sur la facturation électronique.',
  '["Aucune action de conformité n''est requise ni même possible pour l''instant -- aucun mandat n''existe, aucun portail n''existe, et aucun format n''a été publié", "Ne planifiez rien autour d''une date précise de 2026/2027 circulant dans les commentaires du secteur -- aucune ne repose sur un document du gouvernement qatari", "Surveillez l''examen par le Conseil de la Choura, le décret amiri et la publication au Journal officiel, qui sont les véritables signaux du passage du projet à une loi promulguée"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-05-06-qatar-draft-elaw-approved', 'fr',
  'Le Qatar franchit sa première étape législative en matière de facturation électronique -- un mandat reste encore loin',
  'Le Conseil des ministres du Qatar a approuvé un projet de loi sur la facturation électronique et son règlement d''application le 6 mai 2026 -- une première étape réelle, mais pas un mandat. Le projet nécessite encore l''examen du Conseil de la Choura et l''assentiment de l''Émir, aucune date de mise en œuvre ni format n''a été publié, et le Qatar n''a même pas encore mis en œuvre la TVA.',
  '<h3>🇶🇦 Le Qatar franchit sa première étape législative en matière de facturation électronique -- un mandat reste encore loin</h3>
<p>Le 6 mai 2026, le Conseil des ministres du Qatar a approuvé un projet de loi sur la facturation électronique et son règlement d''application -- confirmé par EY, KPMG, PwC et Thomson Reuters/Pagero, qui décrivent tous la même action unique. Il s''agit du premier mouvement législatif concret que ce suivi ait trouvé concernant la facturation électronique qatarie, plaçant le Qatar aux côtés de l''Arabie saoudite, des Émirats arabes unis et d''Oman parmi les États du Golfe travaillant activement à l''instauration d''un mandat.</p>
<p>Mais « projet » signifie exactement cela : la loi doit encore passer l''examen du Conseil de la Choura, puis être soumise à l''Émir pour promulgation, puis être publiée au Journal officiel -- et, à la date de publication de cet article, aucune de ces étapes n''a été confirmée de manière indépendante. Aucune date de mise en œuvre, seuil d''assujettissement, format technique ni structure de sanctions n''a été officiellement publié. Certains commentaires du secteur évoquent une entrée en vigueur en 2027 ou un déploiement à la saoudienne/émiratie, mais rien de tout cela ne repose sur un document du gouvernement qatari. Ce qui souligne le caractère précoce de tout cela : le Qatar n''a même pas encore mis en œuvre la TVA, malgré l''engagement pris à cet effet au titre de l''accord unifié du CCG sur la TVA de 2016 -- un enchaînement inhabituel pour un pays en train de rédiger une loi sur la facturation électronique.</p>'
);

